//! Reads the clause headings of `docs/specs/` into the pages the help skill serves (SKILL-17).
//!
//! The headings are about 95 KB inside 4 MB of spec text. Carrying only them at build time keeps
//! the text out of the binary and leaves no generated file in the tree to regenerate with a spec.

#![forbid(unsafe_code)]

use std::env;
use std::fs;
use std::path::Path;

mod spec_headings {
    include!("src/spec_headings.rs");
}

/// The name of the help skill, which `src/help.rs` holds as `SKILL`. A test there holds the two
/// to each other.
const SKILL: &str = "bravebot-help";

const SPECS: &str = "../../docs/specs";

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=src/spec_headings.rs");
    println!("cargo:rerun-if-changed={SPECS}");

    let mut specs = Vec::new();
    walk(Path::new(SPECS), "", &mut specs);
    specs.sort_by(|a, b| a.0.cmp(&b.0));

    let mut out = String::from("// Generated by build.rs from docs/specs. Do not edit.\n\n");
    out.push_str(&format!(
        "pub const LIST: &str = {:?};\n\npub const SPECS: [(&str, &str); {}] = [\n",
        spec_headings::list(SKILL, &specs),
        specs.len()
    ));
    for (path, spec) in &specs {
        out.push_str(&format!(
            "    ({:?}, {:?}),\n",
            spec_headings::page_id(path),
            spec_headings::page(path, spec)
        ));
    }
    out.push_str("];\n");

    let path =
        Path::new(&env::var("OUT_DIR").expect("cargo sets OUT_DIR")).join("spec_headings.rs");
    fs::write(path, out).expect("write the spec headings");
}

/// Every spec under `dir`, named by its path below the specs directory without the extension.
fn walk(dir: &Path, below: &str, out: &mut Vec<(String, spec_headings::Spec)>) {
    for entry in fs::read_dir(dir).expect("docs/specs exists") {
        let path = entry.expect("read docs/specs").path();
        let name = path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .expect("spec file names are UTF-8");
        if path.is_dir() {
            walk(&path, &format!("{below}{name}/"), out);
        } else if path.extension().is_some_and(|ext| ext == "md") {
            let text = fs::read_to_string(&path).expect("read a spec");
            match spec_headings::parse(&text) {
                Some(spec) => out.push((format!("{below}{name}"), spec)),
                // The directory's README says what the specs are and holds no clause. Any other file
                // that is not a spec would otherwise drop out of the help skill unseen.
                None if path == Path::new(SPECS).join("README.md") => {}
                None => panic!(
                    "{} has no frontmatter with an id, so its clauses cannot be carried",
                    path.display()
                ),
            }
        }
    }
}
